// Notification model for the GetKeja mobile app.
// Represents a user notification from the backend, including search-alert
// notifications generated by the search-alert service.

class NotificationModel {
  NotificationModel({
    required this.id,
    required this.userId,
    this.organisationId,
    required this.eventType,
    required this.category,
    required this.title,
    required this.body,
    this.metadata = const {},
    required this.priority,
    required this.isRead,
    this.readAt,
    this.expiresAt,
    required this.createdAt,
  });

  final String id;
  final String userId;
  final String? organisationId;
  final String eventType;
  final String category;
  final String title;
  final String body;
  final Map<String, dynamic> metadata;
  final String priority;
  final bool isRead;
  final String? readAt;
  final String? expiresAt;
  final String createdAt;

  /// The saved-search identifier embedded in notification metadata, if any.
  String? get savedSearchId => metadata['savedSearchId'] as String?;

  /// The matching listing identifier embedded in notification metadata, if any.
  String? get listingId => metadata['listingId'] as String?;

  /// The matching listing title, if present in metadata.
  String? get listingTitle => metadata['listingTitle'] as String?;

  /// The matching listing location, if present in metadata.
  String? get listingLocation => metadata['listingLocation'] as String?;

  /// The matching listing price, if present in metadata.
  num? get listingPrice => metadata['listingPrice'] as num?;

  /// The saved search name, if present in metadata.
  String? get searchName => metadata['searchName'] as String?;

  /// Safe deep link (getkeja://...) attached by the backend for operational
  /// notifications. Authorization is always re-checked by the target screen.
  String? get deepLink => metadata['deepLink'] as String?;

  /// The compact property summary, if present in metadata.
  String? get summary => metadata['summary'] as String?;

  /// Whether this notification is a search-alert notification.
  bool get isSearchAlert => eventType == 'saved_search.match' || category == 'property';

  factory NotificationModel.fromJson(Map<String, dynamic> json) {
    return NotificationModel(
      id: json['id'] as String,
      userId: json['userId'] as String,
      organisationId: json['organisationId'] as String?,
      eventType: json['eventType'] as String,
      category: json['category'] as String,
      title: json['title'] as String,
      body: json['body'] as String,
      metadata: (json['metadata'] as Map<String, dynamic>? ?? <String, dynamic>{})
          .cast<String, dynamic>(),
      priority: json['priority'] as String? ?? 'normal',
      isRead: json['isRead'] as bool? ?? false,
      readAt: json['readAt'] as String?,
      expiresAt: json['expiresAt'] as String?,
      createdAt: json['createdAt'] as String,
    );
  }

  Map<String, dynamic> toJson() {
    return <String, dynamic>{
      'id': id,
      'userId': userId,
      if (organisationId != null) 'organisationId': organisationId,
      'eventType': eventType,
      'category': category,
      'title': title,
      'body': body,
      'metadata': metadata,
      'priority': priority,
      'isRead': isRead,
      if (readAt != null) 'readAt': readAt,
      if (expiresAt != null) 'expiresAt': expiresAt,
      'createdAt': createdAt,
    };
  }
}

class NotificationListResponse {
  NotificationListResponse({
    required this.notifications,
    required this.success,
  });

  final List<NotificationModel> notifications;
  final bool success;

  factory NotificationListResponse.fromJson(Map<String, dynamic> json) {
    final raw = (json['data'] as List<dynamic>? ?? <dynamic>[]);
    return NotificationListResponse(
      notifications: raw
          .whereType<Map<String, dynamic>>()
          .map(NotificationModel.fromJson)
          .toList(growable: false),
      success: json['success'] as bool? ?? true,
    );
  }
}

class UnreadCountResponse {
  UnreadCountResponse({
    required this.count,
    required this.success,
  });

  final int count;
  final bool success;

  factory UnreadCountResponse.fromJson(Map<String, dynamic> json) {
    return UnreadCountResponse(
      count: (json['data']?['count'] as int? ?? 0),
      success: json['success'] as bool? ?? true,
    );
  }
}
